let generateButton=document.getElementById("generate"),secretKeyInput=document.getElementById("secret-key"),copyButton=document.getElementById("copy"),secretKey=generateSecretKey();function generateSecretKey(){var t="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*(-_=+)";let n="";for(let e=0;e<50;e++)n+=t.charAt(Math.floor(Math.random()*t.length));return n}generateButton.addEventListener("click",function(){secretKeyInput.value=generateSecretKey()}),copyButton.addEventListener("click",function(){secretKeyInput.select(),document.execCommand("copy"),alert("SECRET_KEY copiado com sucesso!")});